import io.agentscope.core.state.*;import io.agentscope.core.message.*;import io.agentscope.core.event.*;import io.agentscope.core.agent.*;import io.agentscope.core.model.*;import io.agentscope.core.permission.*;import io.agentscope.core.tool.*;import io.agentscope.harness.agent.*;import io.agentscope.core.agui.event.AguiEvent;import io.agentscope.core.agui.model.RunAgentInput;import org.ruoyi.ipd.agent.service.*;import org.ruoyi.ipd.agent.domain.*;import org.ruoyi.ipd.agent.*;import org.ruoyi.ipd.security.*;import org.ruoyi.chat.kernel.*;import java.util.*;import java.nio.file.*;import java.util.concurrent.atomic.*;import reactor.core.publisher.*;
public class GSavedCheckpointGuardProbe{
 static void expect(String label,boolean success,Runnable action){boolean passed=false;try{action.run();passed=true;}catch(IllegalArgumentException|IllegalStateException expected){System.out.println(label+".GUARD_REASON="+expected.getMessage());}if(passed!=success)throw new AssertionError(label);System.out.println(label+"=PASS");}
 public static void main(String[]a){boolean failure=false;for(boolean suspended:List.of(false,true))try{run(Path.of(a[0]),suspended);}catch(AssertionError error){failure=true;System.out.println("NEGATIVE_FAILURE="+error.getMessage());}if(failure)throw new AssertionError("guard negative failed; see retained evidence");}
 static void run(Path root,boolean suspended){String name=suspended?"probe_suspend":"probe_ask";var states=new InMemoryAgentStateStore();var toolkit=new Toolkit();toolkit.registerAgentTool(new ToolBase(ToolBase.builder().name(name).description("synthetic").inputSchema(Map.of("type","object"))){public Mono<ToolResultBlock> callAsync(ToolCallParam p){return Mono.just(ToolResultBlock.suspended(p.getToolUseBlock()));}});var counter=new AtomicInteger();Model model=new Model(){public String getModelName(){return "stub";}public Flux<ChatResponse> stream(List<Msg>m,List<ToolSchema>t,GenerateOptions o){boolean first=counter.incrementAndGet()==1;return Flux.just(ChatResponse.builder().id("stub"+counter.get()).content(first?List.of(ToolUseBlock.builder().id("pending").name(name).input(Map.of()).content("{}").build()):List.of(TextBlock.builder().text("synthetic").build())).finishReason(first?"tool_calls":"stop").build());}};var perm=PermissionContextState.builder();if(suspended)perm.addAllowRule(name,new PermissionRule(name,null,PermissionBehavior.ALLOW,"synthetic"));else perm.addAskRule(name,new PermissionRule(name,null,PermissionBehavior.ASK,"synthetic"));var scope=KernelScopeKey.of("9","7",ProjectAgentConstants.AGENT_ID,"42");try(var agent=HarnessAgent.builder().name("saved-checkpoint").workspace(root.resolve(name)).model(model).toolkit(toolkit).stateStore(states).permissionContext(perm.build()).build()){
 var runtime=scope.toRuntimeContext();agent.streamEvents(Msg.builder().role(MsgRole.USER).textContent("synthetic request").build(),runtime).collectList().block();var cp=states.getVersioned(scope.userId(),scope.sessionId(),"agent_state",AgentState.class);if(!cp.isPresent())throw new AssertionError("real SDK failed save");var call=cp.value().getContext().stream().flatMap(msg->msg.getContentBlocks(ToolUseBlock.class).stream()).filter(c->c.getId().equals("pending")).findFirst().orElseThrow();System.out.println(name+".ACTUAL_STATE="+call.getState()+" VERSION="+cp.version());for(var msg:cp.value().getContext())for(var block:msg.getContentBlocks(ToolResultBlock.class))System.out.println("STORED_TOOL_RESULT id="+block.getId()+" state="+block.getState()+" suspended="+block.isSuspended());
 var meta=new HashMap<String,Object>();meta.put("toolName",name);meta.put("toolInput",call.getInput());meta.put("toolContent",io.agentscope.core.util.JsonUtils.resolveToolCallArgsJson(call));meta.put("agentscope.interruptKind",suspended?"tool_suspended":"permission_confirm");var interrupt=new AguiEvent.Interrupt("reply:pending","tool_call","synthetic","pending",null,null,meta);var pending=Map.of("reply:pending",interrupt);var pause=new ProjectAgentAguiPauseResumeService.PauseCheckpoint(1,1,cp.version(),"42","42","7",pending);var run=IpdAgentRun.builder().id(42L).projectId(9L).personId(7L).version(1).status("WAITING_APPROVAL").build();var actor=new IpdActor(7L,"owner","PM",null);var input=RunAgentInput.builder().threadId("42").runId("42").build();var guard=new ProjectAgentAguiCheckpointGuard(states,(person,in)->Map.of());expect(name+".actualSavedProducer",true,()->guard.validate(actor,run,pause,input));expect(name+".wrongVersion",false,()->guard.validate(actor,run,new ProjectAgentAguiPauseResumeService.PauseCheckpoint(1,1,cp.version()+1,"42","42","7",pending),input));expect(name+".missingCheckpoint",false,()->new ProjectAgentAguiCheckpointGuard(new InMemoryAgentStateStore(),(person,in)->Map.of()).validate(actor,run,pause,input));expect(name+".wrongOwner",false,()->guard.validate(new IpdActor(8L,"other","PM",null),run,pause,input));
 var wrongStates=new InMemoryAgentStateStore();wrongStates.saveIfVersion(scope.userId(),scope.sessionId(),"agent_state",AgentState.builder().userId("wrong-user").sessionId(scope.sessionId()).context(cp.value().getContext()).build(),AgentStateStore.UNVERSIONED);expect(name+".wrongSavedScope",false,()->new ProjectAgentAguiCheckpointGuard(wrongStates,(person,in)->Map.of()).validate(actor,run,pause,input));
 var changed=new HashMap<>(meta);changed.put("toolContent","{ }");var wrong=new AguiEvent.Interrupt("reply:pending","tool_call","synthetic","pending",null,null,changed);expect(name+".forgedRaw",false,()->guard.validate(actor,run,new ProjectAgentAguiPauseResumeService.PauseCheckpoint(1,1,cp.version(),"42","42","7",Map.of("reply:pending",wrong)),input));
 for(String key:List.of("toolName","toolInput")){var forged=new HashMap<>(meta);forged.put(key,key.equals("toolInput")?Map.of("changed",true):"wrong-tool");var bad=new AguiEvent.Interrupt("reply:pending","tool_call","synthetic","pending",null,null,forged);expect(name+".forged-"+key,false,()->guard.validate(actor,run,new ProjectAgentAguiPauseResumeService.PauseCheckpoint(1,1,cp.version(),"42","42","7",Map.of("reply:pending",bad)),input));}var badId=new AguiEvent.Interrupt("reply:other","tool_call","synthetic","other",null,null,meta);expect(name+".forged-id",false,()->guard.validate(actor,run,new ProjectAgentAguiPauseResumeService.PauseCheckpoint(1,1,cp.version(),"42","42","7",Map.of("reply:other",badId)),input));
 if(!suspended){var decision=Msg.builder().role(MsgRole.USER).textContent("synthetic deny").metadata(Map.of(Msg.METADATA_CONFIRM_RESULTS,List.of(new ConfirmResult(false,call)))).build();agent.streamEvents(decision,runtime).collectList().block();var done=states.getVersioned(scope.userId(),scope.sessionId(),"agent_state",AgentState.class);expect(name+".finishedCheckpoint",false,()->guard.validate(actor,run,new ProjectAgentAguiPauseResumeService.PauseCheckpoint(1,1,done.version(),"42","42","7",pending),input));}
 }} }
